-------------------------------------- Urheberrecht --------------- by [LA]Leyynen ------------------- 2012 ------------------------------------------lieferantModels = { [456]=true }function startLieferantJob_func ( player )	if laGetElementData ( player, "job" ) == "lieferant" then		toggleControl ( player, "fire", true )		toggleControl ( player, "enter_exit", true )		laSetElementData( player, "nodmzone", 0 )		local pname = getPlayerName ( player )		matchDim = tonumber ( laGetElementData ( player, "playerid" ) ) + 1		setElementInterior ( player, 0 )		setElementDimension ( player, matchDim )		_G["Transporter"..pname] = createVehicle ( 456,-1578.897, 122.55, 3.554 )		setVehicleDamageProof ( _G["Transporter"..pname], true )		setElementDimension ( _G["Transporter"..pname], matchDim )		laSetElementData ( player, "isLieferant", true )		warpPedIntoVehicle ( player, _G["Transporter"..pname] )		_G["LieferantMarker1"..pname] = createMarker ( -1500.53, 920.3, 6.1875, "checkpoint", 10, 255, 255, 255, 150, player )		_G["LieferantBlip1"..pname] = createBlip ( -1500.53, 920.3, 6.1875, 0, 2, 255, 0, 0, 255, 0, 99999.0, player )		setElementDimension ( _G["LieferantMarker1"..pname], matchDim )		setElementDimension ( _G["LieferantBlip1"..pname], matchDim )		_G["LieferantMarker2"..pname] = createMarker ( -1639.32, 1211.42, 6.558, "checkpoint", 10, 255, 255, 255, 150, player )		_G["LieferantBlip2"..pname] = createBlip ( -1639.32, 1211.42, 6.558, 0, 2, 255, 0, 0, 255, 0, 99999.0, player )		_G["LieferantMarker3"..pname] = createMarker ( -2063.39, 1325.92, 6.59, "checkpoint", 10, 255, 255, 255, 150, player )		_G["LieferantBlip3"..pname] = createBlip ( -2063.39, 1325.92, 6.59, 0, 2, 255, 0, 0, 255, 0, 99999.0, player )		_G["LieferantMarker4"..pname] = createMarker ( -2675.35, 1308.11, 54.83, "checkpoint", 10, 255, 255, 255, 150, player )		_G["LieferantBlip4"..pname] = createBlip ( -2675.35, 1308.11, 54.83, 0, 2, 255, 0, 0, 255, 0, 99999.0, player )		_G["LieferantMarker5"..pname] = createMarker ( -2430.6, 2326.88, 4.3936, "checkpoint", 10, 255, 255, 255, 150, player )		_G["LieferantBlip5"..pname] = createBlip ( -2430.6, 2326.88, 4.3936, 0, 2, 255, 0, 0, 255, 0, 99999.0, player )		for i = 2, 5 do			setElementDimension ( _G["LieferantBlip"..i..pname], -1 )			setElementDimension ( _G["LieferantMarker"..i..pname], -1 )		end		outputChatBox ( "[AUFGABE]: Du musst die angegebene Route fahren, um deinen Lohn zu erhalten!", player, 0, 100, 200 )		outputChatBox ( "[INFO]: Den Transporter findest du weiter vorne!", player, 200, 200, 0 )	else		outputChatBox ( "Du bist kein Lieferant!", player, 150, 0, 0 )	endendaddCommandHandler("auftrag",startLieferantJob_func)function LieferantMarkerHit( hitElement, mDim )    	if getElementType ( hitElement ) == "player" then		local player = hitElement		local matchDim = tonumber ( laGetElementData ( player, "playerid" ) ) + 1		local pname = getPlayerName ( player )		if source == _G["LieferantMarker1"..pname] and mDim then			setElementDimension ( _G["LieferantMarker1"..pname], -1 )			setElementDimension ( _G["LieferantBlip1"..pname], -1 )			setElementDimension ( _G["LieferantMarker2"..pname], matchDim )			setElementDimension ( _G["LieferantBlip2"..pname], matchDim )			playSoundFrontEnd ( player, 43 )		elseif source == _G["LieferantMarker2"..pname] and mDim then			setElementDimension ( _G["LieferantMarker2"..pname], -1 )			setElementDimension ( _G["LieferantBlip2"..pname], -1 )			setElementDimension ( _G["LieferantMarker3"..pname], matchDim )			setElementDimension ( _G["LieferantBlip3"..pname], matchDim )			playSoundFrontEnd ( player, 43 )		elseif source == _G["LieferantMarker3"..pname] and mDim then			setElementDimension ( _G["LieferantMarker3"..pname], -1 )			setElementDimension ( _G["LieferantBlip3"..pname], -1 )			setElementDimension ( _G["LieferantMarker4"..pname], matchDim )			setElementDimension ( _G["LieferantBlip4"..pname], matchDim )			playSoundFrontEnd ( player, 43 )		elseif source == _G["LieferantMarker4"..pname] and mDim then			setElementDimension ( _G["LieferantMarker4"..pname], -1 )			setElementDimension ( _G["LieferantBlip4"..pname], -1 )			setElementDimension ( _G["LieferantMarker5"..pname], matchDim )			setElementDimension ( _G["LieferantBlip5"..pname], matchDim )			playSoundFrontEnd ( player, 43 )		elseif source == _G["LieferantMarker5"..pname] and mDim then			setElementDimension ( _G["LieferantMarker5"..pname], -1 )			setElementDimension ( _G["LieferantBlip5"..pname], -1 )			outputChatBox ( "Glückwunsch, du hast es geschafft! Du kriegst 500$!", player, 0, 125, 0 )			laSetElementData ( player, "money", laGetElementData ( player, "money" ) + 500 )			givePlayerMoney ( player, 500 )			playSoundFrontEnd ( player, 40 )			takePlayerMoney ( player, 750 )			laSetElementData ( player, "isLieferant", false )			destroyElement ( _G["Transporter"..pname] )			setTimer ( spawnAtLieferantbase, 1000, 1, player )			triggerClientEvent ( player, "HudEinblendenMoney", getRootElement() )		end	endendaddEventHandler( "onMarkerHit", getRootElement(), LieferantMarkerHit )function spawnAtLieferantbase ( player )	setElementPosition ( player, -1569.897, 131.55, 3.554 )	setElementDimension ( player, 0 )end